#include <stdio.h>
#include <string.h>

#define MAX 100

void lcs(char *a, char *b) {
    int m = strlen(a), n = strlen(b);
    int dp[MAX][MAX] = {0};
    for (int i = 1; i <= m; i++) {
        for (int j = 1; j <= n; j++) {
            if (a[i-1] == b[j-1]) dp[i][j] = dp[i-1][j-1] + 1;
            else dp[i][j] = (dp[i-1][j] > dp[i][j-1]) ? dp[i-1][j] : dp[i][j-1];
        }
    }
    printf("LCS Length: %d\n", dp[m][n]);
}

int main() {
    lcs("ABCBDAB", "BDCABA");
    return 0;
}
